VALUES (667216, 'tt10365998', NULL, 'Infinity Pool', 'Infinity Pool', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/cQKyNm0Nz6KWiDBQF9w4aZAmOfC.jpg', 'https://image.tmdb.org/t/p/original/1xhcEecvRJXQ2OAVO7l9btlrN6D.jpg', 'While staying at an isolated island resort, James and Em are enjoying a perfect vacation of pristine beaches, exceptional staff, and soaking up the sun. But guided by the seductive and mysterious Gabi, they venture outside the resort grounds and find themselves in a culture filled with violence, hedonism, and untold horror. A tragic accident leaves them facing a zero tolerance policy for crime: either you''ll be executed, or, if you’re rich enough to afford it, you can watch yourself die instead.', NULL, NULL, 4.7957, 6.021, 0, 2.92826923076923044e+01, '2026-07-15 12:01:52', '2026-11-28 04:11:46')
