VALUES (204436, 'tt1181840', NULL, 'Jack and the Cuckoo-Clock Heart', 'Jack et la mécanique du cœur', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/ZSrU2mvlzM5Jr30XtKCU1fziIj.jpg', 'https://image.tmdb.org/t/p/original/rjXK74vrvmFMN0vuFw3TViZ18Ha.jpg', 'Jack is born with his heart frozen solid on the coldest day in history. A wise midwife saves him by replacing it with a cuckoo clock. Now Jack must abide by three rules to keep his mechanical heart safe: never touch the clock''s hands, master his anger, and never fall in love. He tries his best, but when he meets a girl named Acacia he falls in love, threatening the delicate balance of his artificial heart.', NULL, NULL, 3.6689, 7.227, 0, 1.26933333333333315e+01, '2026-07-15 12:01:52', '2026-11-28 04:11:46')
