VALUES (2122, 'tt0118375', NULL, 'King of the Hill', 'King of the Hill', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/lvf0q6kX0NCjFp7VxEuC6ArBa42.jpg', 'https://image.tmdb.org/t/p/original/4CSdS9p0AhLhxCo1hGuQINiE2Sa.jpg', 'Set in Texas, this animated series follows the life of propane salesman Hank Hill, who lives with his overly confident substitute Spanish teacher wife Peggy, wannabe comedian son Bobby, and naive niece Luanne. Hank has conservative views about God, family, and country, but his values and ethics are often challenged by the situations he, his family, and his beer-drinking neighbors/buddies find themselves in.', NULL, NULL, 118.5572, 7.413, 0, 8.02333333333333342e+00, '2026-08-04 03:20:13', '2026-11-28 04:11:46')
