VALUES (11698, 'tt0075276', NULL, 'Stroszek', 'Stroszek', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/wDq9ytRxoVpICRcx1BvagmXhd4t.jpg', 'https://image.tmdb.org/t/p/original/eM3Kbzk9v03wJc0yoSC0QGEOU9C.jpg', 'Bruno Stroszek is released from prison and warned to stop drinking. He has few skills and fewer expectations: with a glockenspiel and an accordion, he ekes out a living as a street musician. He befriends Eva, a prostitute down on her luck and they join his neighbor, Scheitz, an elderly eccentric, when he leaves Germany to live in Wisconsin.', NULL, NULL, 1.6081, 7.296, 0, 10.918, '2026-08-04 03:20:13', '2026-11-28 04:11:46')
