VALUES (283587, 'tt1365050', NULL, 'Beasts of No Nation', 'Beasts of No Nation', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/1D4vcJmJc58WXarpRtwgd2do9Rg.jpg', 'https://image.tmdb.org/t/p/original/vDfbeUK3OhoeyQRlUODwfSy6tyE.jpg', 'Based on the experiences of Agu, a child fighting in the civil war of a West African country. Follows Agu''s journey as he''s forced to join a group of soldiers. While he fears his commander and many of the men around him, his fledgling childhood has been brutally shattered by the war raging through his country, and he is at first torn between conflicting revulsion and fascination.', NULL, NULL, 2.7563, 7.577, 0, 1.55122222222222205e+01, '2026-08-04 03:20:13', '2026-11-28 04:11:46')
