VALUES (12487, 'tt0361668', NULL, 'Gozu', '極道恐怖大劇場 牛頭 GOZU', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/mo5L0XzMYmLhdsvgA40qlYiHhAF.jpg', 'https://image.tmdb.org/t/p/original/wrV17pXZjFnnUtdGYZaz9q7mslR.jpg', 'Minami mistakenly kills a gangster associate of his named Brother. Almost as soon as the murder takes place, the body of the deceased man is gone, prompting Minami to conduct a search. While looking, he finds a mysterious isolated hotel where he decides to take a rest. Not only are the front desk clerks a bit strange, but even the ambiance feels unusual. Minami soon realizes he may have gotten more than he bargained for.', NULL, NULL, 1.8594, 6.8, 0, 15.75375, '2026-08-18 01:44:45', '2026-11-28 04:11:46')
